import type {Metadata} from "next";import Link from "next/link";import Header from "@/components/Header";import SearchBox from "@/components/SearchBox";import GameGlyph from "@/components/GameGlyph";import {getGameCatalog} from "@/lib/catalog";import {rankGameSearch} from "@/lib/search";import {compactNumber} from "@/lib/format";
export const dynamic="force-dynamic";export const metadata:Metadata={title:"게임 검색",robots:{index:false,follow:true}};
export default async function Search({searchParams}:{searchParams:Promise<{q?:string}>}){const {q=""}=await searchParams;const games=await getGameCatalog();const results=q?rankGameSearch(games,q):[];return <><Header games={games}/><main className="page"><div className="page-title"><h1>게임 검색</h1><p>한글 이름, 영어 이름, 흔한 표기를 같은 Game Entity에 연결합니다.</p></div><SearchBox games={games}/>{q&&<section style={{marginTop:28}}><div className="section-head"><h2>‘{q}’ 검색 결과 {results.length}개</h2></div>{results.length?results.map(g=><Link className="search-result" key={g.universeId} href={`/game/${g.slug}`}><span style={{display:"flex",gap:12,alignItems:"center"}}><GameGlyph name={g.nameKo}/><span><strong>{g.nameKo}</strong><br/><small>{g.name}</small></span></span><span>{compactNumber(g.playing)}명</span></Link>):<div className="no-data"><strong>찾는 게임이 없나요?</strong><p>영문명이나 다른 표기로 다시 검색해 보세요. 결과 없음 Query는 향후 별칭 개선에만 최소한으로 활용합니다.</p></div>}</section>}</main></>}
